&lt;ul class=&quot;ul1&quot; style=&quot;text-align: justify;&quot;&gt;
&lt;li class=&quot;li1&quot; style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Consistent achievement of gross loan portfolio targets and portfolio profit targets.&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
